INSERT INTO fontes_juridicas (escritorioId,tipo,identificador,orgao,area,titulo,texto,tags,embedding) VALUES
(NULL,'sumula','Súmula 297 do STJ','STJ','revisional','Súmula 297 do STJ','O Código de Defesa do Consumidor é aplicável às instituições financeiras.','consumidor,banco,revisional','[0.01,0.02,0.03]'),
(NULL,'sumula','Súmula 382 do STJ','STJ','revisional','Súmula 382 do STJ','A estipulação de juros remuneratórios superiores a 12% ao ano, por si só, não indica abusividade.','juros,revisional','[0.01,0.02,0.03]'),
(NULL,'sumula','Súmula 539 do STJ','STJ','revisional','Súmula 539 do STJ','É permitida a capitalização de juros com periodicidade inferior à anual em contratos celebrados com instituições integrantes do Sistema Financeiro Nacional a partir de 31/3/2000, desde que expressamente pactuada.','capitalizacao,juros','[0.01,0.02,0.03]'),
(NULL,'sumula','Súmula 72 do STJ','STJ','busca_apreensao','Súmula 72 do STJ','A comprovação da mora é imprescindível à busca e apreensão do bem alienado fiduciariamente.','busca e apreensao,mora','[0.01,0.02,0.03]'),
(NULL,'tese','Tema 1.061 do STJ','STJ','revisional','Tema 1.061 do STJ','A abusividade da tarifa de avaliação do bem e do seguro de proteção financeira deve ser aferida no caso concreto.','tarifa,seguro','[0.01,0.02,0.03]'),
(NULL,'lei','CDC art. 42, parágrafo único','Congresso Nacional','revisional','CDC art. 42, parágrafo único','O consumidor cobrado em quantia indevida tem direito à repetição do indébito, por valor igual ao dobro do que pagou em excesso, acrescido de correção monetária e juros legais, salvo hipótese de engano justificável.','repeticao,indebito','[0.01,0.02,0.03]'),
(NULL,'lei','Decreto-Lei 911/69, art. 3º','Congresso Nacional','busca_apreensao','Decreto-Lei 911/69, art. 3º','O proprietário fiduciário ou credor poderá, desde que comprovada a mora, requerer contra o devedor a busca e apreensão do bem alienado fiduciariamente.','busca e apreensao','[0.01,0.02,0.03]'),
(NULL,'precedente','TJCE — Apelação 0123456-78.2025.8.06.0001','TJCE','revisional','TJCE — Apelação 0123456-78.2025.8.06.0001','Revisional de contrato bancário. Capitalização mensal expressamente pactuada. Tarifa de avaliação do bem não comprovada. Abusividade reconhecida em parte. Recurso parcialmente provido.','tjce,capitalizacao,tarifa','[0.01,0.02,0.03]'),
(NULL,'precedente','TJSP — Apelação 1004567-12.2025.8.26.0100','TJSP','revisional','TJSP — Apelação 1004567-12.2025.8.26.0100','Contrato bancário. Juros remuneratórios dentro da média de mercado. Manutenção da sentença de improcedência.','tjsp,juros',NULL),
(NULL,'precedente','TJMG — Apelação 5001234-55.2025.8.13.0024','TJMG','busca_apreensao','TJMG — Apelação 5001234-55.2025.8.13.0024','Busca e apreensão. Notificação extrajudicial enviada ao endereço do contrato. Mora comprovada. Sentença mantida.','tjmg,mora',NULL);
